import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  last_error: string | null;
  idempotency_key: string;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ClaimedErasureRequest extends ErasureRequestRow {}

export const MAX_ERASURE_ATTEMPTS = 12;

export function erasureRequestBody(row: ErasureRequestRow): Record<string, unknown> {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    completedAt: row.completed_at,
    lastError: row.last_error,
  };
}

export function erasureRequestHash(customerId: string): string {
  return createHash('sha256').update(JSON.stringify({ customerId })).digest('hex');
}

export class ErasureRepository {
  async customerExists(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async findRequest(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  /**
   * Reserves an idempotency key for erasure creation. Returns a cached response
   * for a replay, throws 409 on key reuse for a different request, or returns
   * undefined when this is a fresh request that should proceed.
   */
  async reserveIdempotency(
    client: pg.PoolClient,
    merchantId: string,
    key: string,
    hash: string,
  ): Promise<{ status: number; body: unknown } | undefined> {
    const inserted = await client.query(
      `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
       VALUES($1,'erasure-request',$2,$3,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
      [merchantId, key, hash],
    );
    if (inserted.rowCount) return undefined;
    const existing = await client.query<{ request_hash: string; response_status: number | null; response_body: unknown }>(
      `SELECT request_hash,response_status,response_body FROM operations.idempotency_keys
       WHERE merchant_id=$1 AND scope='erasure-request' AND key=$2 FOR UPDATE`,
      [merchantId, key],
    );
    const row = existing.rows[0];
    if (!row || row.request_hash !== hash) {
      throw Object.assign(new Error('idempotency key reused with different request'), { statusCode: 409 });
    }
    if (row.response_status === null) {
      throw Object.assign(new Error('request with this idempotency key is in progress'), { statusCode: 409 });
    }
    return { status: row.response_status, body: row.response_body };
  }

  async completeIdempotency(
    client: pg.PoolClient,
    merchantId: string,
    key: string,
    status: number,
    body: unknown,
  ): Promise<void> {
    await client.query(
      `UPDATE operations.idempotency_keys SET response_status=$3,response_body=$4
       WHERE merchant_id=$1 AND scope='erasure-request' AND key=$2`,
      [merchantId, key, status, body],
    );
  }

  /** Creates a request or returns the existing one for this customer (one per customer). */
  async upsertRequest(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow> {
    const inserted = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
       VALUES($1,$2,$3) ON CONFLICT (customer_id) DO NOTHING RETURNING *`,
      [merchantId, customerId, idempotencyKey],
    );
    if (inserted.rows[0]) return inserted.rows[0];
    const existing = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    return existing.rows[0]!;
  }

  async resetToPending(client: pg.PoolClient, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='pending', next_attempt_at=now(), last_error=NULL, updated_at=now()
       WHERE id=$1 AND status='failed' RETURNING *`,
      [requestId],
    );
    return result.rows[0];
  }

  async claim(): Promise<ClaimedErasureRequest | undefined> {
    const result = await pool.query<ClaimedErasureRequest>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, next_attempt_at=NULL, updated_at=now()
       WHERE id=(SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed') AND next_attempt_at<=now()
         ORDER BY next_attempt_at, created_at FOR UPDATE SKIP LOCKED LIMIT 1)
       RETURNING *`,
    );
    return result.rows[0];
  }

  async complete(client: pg.PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', completed_at=now(), last_error=NULL, next_attempt_at=NULL, updated_at=now()
       WHERE id=$1`,
      [requestId],
    );
  }

  async fail(client: pg.PoolClient, requestId: string, attempts: number, code: string): Promise<void> {
    if (attempts >= MAX_ERASURE_ATTEMPTS) {
      await client.query(
        `UPDATE customers.erasure_requests
         SET status='failed', last_error=$2, next_attempt_at=NULL, updated_at=now() WHERE id=$1`,
        [requestId, code],
      );
      return;
    }
    const delay = Math.min(300, 2 ** Math.min(attempts, 8));
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='failed', last_error=$2, next_attempt_at=now()+($3 || ' seconds')::interval, updated_at=now()
       WHERE id=$1`,
      [requestId, code, delay],
    );
  }

  /** Object keys that must be purged from object storage before records are anonymized. */
  async gatherObjectKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND object_key IS NOT NULL`,
      [merchantId, customerId],
    );
    return result.rows.map((row) => row.object_key);
  }

  /**
   * Anonymizes personal data across every PayFlow-controlled table while
   * preserving the financial meaning of retained records. Every statement is
   * idempotent so a resumed attempt converges on the same result.
   */
  async anonymizeCustomerData(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<void> {
    // Customer profile tombstone (keeps the id handle for retained financial rows).
    await client.query(
      `UPDATE customers.customers
       SET email='erased+'||id::text||'@erased.invalid', name='Erased customer', phone=NULL,
           external_reference='erased:'||id::text, metadata='{}'::jsonb, status='erased',
           version=version+1, updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );

    // Direct personal data owned by the customer aggregate.
    await client.query(`DELETE FROM customers.addresses WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM customers.contacts WHERE customer_id=$1`, [customerId]);
    await client.query(
      `DELETE FROM customers.support_messages WHERE ticket_id IN
         (SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1)`,
      [customerId],
    );
    await client.query(
      `DELETE FROM customers.support_tickets WHERE id IN
         (SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1)`,
      [customerId],
    );
    await client.query(`DELETE FROM customers.support_participants WHERE customer_id=$1`, [customerId]);

    // Payment method references: keep the id for financial records, revoke and strip PII.
    await client.query(
      `UPDATE customers.payment_method_refs
       SET provider_token='revoked:'||id::text, brand=NULL, last4=NULL, billing_name=NULL,
           billing_address=NULL, status='revoked'
       WHERE customer_id=$1`,
      [customerId],
    );

    // Retained financial records: keep amounts/status, drop identifying snapshots.
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=jsonb_build_object('id',customer_id,'status','erased'),
           description=NULL, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.refunds SET customer_email=NULL, reason='redacted'
       WHERE merchant_id=$1 AND payment_intent_id IN
         (SELECT id FROM payments.payment_intents WHERE customer_id=$2)`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=jsonb_build_object('status','erased'), object_key=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Provider sandbox profile (PayFlow-controlled copy of the customer).
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email='erased', name='Erased', external_reference='erased', updated_at=now()
       WHERE payflow_customer_id=$1`,
      [customerId],
    );

    // Operational records that store or expose PII.
    await client.query(
      `DELETE FROM operations.analytics_events WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(`DELETE FROM operations.notification_preferences WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM operations.notifications WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM operations.email_deliveries WHERE customer_id=$1`, [customerId]);

    // Pending receipt jobs would otherwise render a PII receipt from a stale snapshot.
    await client.query(
      `UPDATE operations.jobs
       SET payload=jsonb_set(payload,'{customerSnapshot}',jsonb_build_object('status','erased'),true)
       WHERE queue='documents' AND job_type='generate_receipt' AND payload->>'customerId'=$1::text`,
      [customerId],
    );

    // Outbox payloads may still carry PII for this customer; redact it.
    await client.query(
      `UPDATE operations.outbox_events
       SET payload = (payload - 'email' - 'name' - 'phone' - 'externalReference' - 'metadata'
                       - 'customerEmail' - 'billingName' - 'customerSnapshot' - 'customer')
                    || jsonb_build_object('erased', true)
       WHERE merchant_id=$1 AND (aggregate_id=$2::uuid OR payload->>'customerId'=$2::text)`,
      [merchantId, customerId],
    );

    // Document manifests are removed once the underlying objects are purged.
    await client.query(
      `DELETE FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }
