import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import {
  ErasureRepository,
  erasureRequestBody,
  erasureRequestHash,
  type ErasureRequestRow,
} from './erasure-repository.js';

function isNotFound(error: unknown): boolean {
  if (error && typeof error === 'object') {
    const code = (error as { code?: unknown }).code;
    if (typeof code === 'string' && /NoSuchKey|NoSuchObject|NotFound/i.test(code)) return true;
    const message = (error as { message?: unknown }).message;
    if (typeof message === 'string' && /not found|nosuchkey/i.test(message)) return true;
  }
  return false;
}

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async createRequest(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: Record<string, unknown> }> {
    // Do not reveal information or change data when the customer is absent.
    if (!(await this.repository.customerExists(merchantId, customerId))) {
      throw Object.assign(new Error('customer not found'), { statusCode: 404 });
    }
    const hash = erasureRequestHash(customerId);
    return await transaction(async (client) => {
      const replay = await this.repository.reserveIdempotency(client, merchantId, idempotencyKey, hash);
      if (replay) {
        return { status: replay.status, body: replay.body as Record<string, unknown> };
      }
      let row = await this.repository.upsertRequest(client, merchantId, customerId, idempotencyKey);
      // Reposting a failed request is allowed and re-queues cleanup without a new id.
      if (row.status === 'failed') {
        const reset = await this.repository.resetToPending(client, row.id);
        if (reset) row = reset;
      }
      const body = erasureRequestBody(row);
      await this.repository.completeIdempotency(client, merchantId, idempotencyKey, 202, body);
      return { status: 202, body };
    });
  }

  async getRequest(merchantId: string, requestId: string): Promise<Record<string, unknown>> {
    const row = await this.repository.findRequest(merchantId, requestId);
    if (!row) throw Object.assign(new Error('erasure request not found'), { statusCode: 404 });
    return erasureRequestBody(row);
  }

  /** Runs the destructive cleanup for a claimed request. Idempotent and resumable. */
  async runCleanup(request: ErasureRequestRow): Promise<void> {
    const objectKeys = await this.repository.gatherObjectKeys(request.merchant_id, request.customer_id);
    await this.purgeObjects(objectKeys);
    await transaction(async (client) => {
      await this.repository.anonymizeCustomerData(client, request.merchant_id, request.customer_id);
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASED, aggregateType: 'customer',
        aggregateId: request.customer_id, merchantId: request.merchant_id, correlationId: uuid(),
        payload: { customerId: request.customer_id, erasedAt: new Date().toISOString() },
      });
      await this.repository.complete(client, request.id);
    });
  }

  async fail(request: ErasureRequestRow, error: unknown): Promise<void> {
    const code = error instanceof Error && /object|store|minio/i.test(error.message)
      ? 'object_store_unavailable'
      : 'cleanup_failed';
    await transaction(async (client) => await this.repository.fail(client, request.id, request.attempts, code));
    logger.warn({ error, requestId: request.id, customerId: request.customer_id }, 'erasure cleanup failed');
  }

  private async purgeObjects(objectKeys: string[]): Promise<void> {
    for (const key of objectKeys) {
      try {
        await objectStore.removeObject(DOCUMENT_BUCKET, key);
      } catch (error) {
        if (isNotFound(error)) continue;
        throw Object.assign(new Error('object store unavailable'), { cause: error });
      }
    }
  }
