{"command":"create","file_text":"import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { authenticate } from '../../../packages/auth/src/api-key.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { ErasureRepository } from './erasure-repository.js';
import { ErasureService } from './erasure-service.js';

const idempotencyKeySchema = z.string().min(8).max(200);

/** Public erasure API endpoints owned by the customer bounded context. */
export async function erasureRoutes(app: FastifyInstance): Promise<void> {
  const service = new ErasureService();

  app.post('/v1/customers/:customerId/erasure-requests', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { customerId } = z.object({ customerId: z.string().uuid() }).parse(request.params);
    const key = request.headers['idempotency-key'];
    const parsedKey = idempotencyKeySchema.safeParse(key);
    if (!parsedKey.success) return reply.code(400).send({ error: 'valid_idempotency_key_required' });
    const result = await service.createRequest(principal.merchantId, customerId, parsedKey.data);
    return reply.code(result.status).send(result.body);
  });

  app.get('/v1/erasure-requests/:requestId', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { requestId } = z.object({ requestId: z.string().uuid() }).parse(request.params);
    return reply.send(await service.getRequest(principal.merchantId, requestId));
  });
}

/** Background worker that drains erasure requests asynchronously. */
export async function startErasureWorker(signal: AbortSignal): Promise<void> {
  const service = new ErasureService();
  const repository = new ErasureRepository();
  while (!signal.aborted) {
    let request;
    try {
      request = await repository.claim();
    } catch (error) {
      logger.warn({ error }, 'erasure worker claim failed');
      await new Promise((resolve) => setTimeout(resolve, 1_000));
      continue;
    }
    if (!request) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      continue;
    }
    try {
      await service.runCleanup(request);
    } catch (error) {
      await service.fail(request, error);
    }
  }
