{"command":"create","file_text":"import assert from 'node:assert/strict';
import { Redis } from 'ioredis';
import { config } from '../packages/config/src/index.js';
import { pool } from '../packages/database/src/pool.js';
import { CUSTOMER_INDEX, searchClient } from '../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../packages/storage/src/minio.js';

const customerId = process.env.ERASURE_CUSTOMER_ID;
const requestId = process.env.ERASURE_REQUEST_ID;
const apiKey = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const gateway = process.env.GATEWAY_URL ?? 'http://localhost:3000';

assert.ok(customerId, 'ERASURE_CUSTOMER_ID required');

async function api(path: string): Promise<{ status: number; body: unknown }> {
  const response = await fetch(`${gateway}${path}`, { headers: { authorization: `Bearer ${apiKey}` } });
  return { status: response.status, body: await response.json().catch(() => null) };
}

// 1. Erasure request is completed.
const status = (await api(`/v1/erasure-requests/${requestId}`)).body as { status: string; lastError: string | null };
assert.equal(status.status, 'completed');

// 2. Customer row is anonymized (tombstone), still resolvable for financial refs.
const customer = (await api(`/v1/customers/${customerId}`)).body as Record<string, unknown>;
assert.equal(customer.status, 'erased');
assert.match(String(customer.email), /erased\+.*@erased\.invalid/);
assert.equal(customer.name, 'Erased customer');
assert.equal(customer.phone, null);
assert.match(String(customer.external_reference), /^erased:/);
assert.deepEqual(customer.metadata, {});

// 3. No personal data remains in customer-owned tables.
const pii = await pool.query<{ table: string; count: number }>(`
  SELECT 'addresses' AS table, count(*)::int count FROM customers.addresses WHERE customer_id=$1
  UNION ALL SELECT 'contacts', count(*)::int FROM customers.contacts WHERE customer_id=$1
  UNION ALL SELECT 'support_participants', count(*)::int FROM customers.support_participants WHERE customer_id=$1
  UNION ALL SELECT 'support_messages', count(*)::int FROM customers.support_messages WHERE author_id=$1
`, [customerId]);
for (const row of pii.rows) assert.equal(row.count, 0, `${row.table} still has rows`);

// 4. Payment methods revoked and stripped of PII.
const methods = await pool.query(`SELECT provider_token,billing_name,billing_address,last4,brand,status FROM customers.payment_method_refs WHERE customer_id=$1`, [customerId]);
assert.equal(methods.rowCount, 1);
const m = methods.rows[0]!;
assert.equal(m.status, 'revoked');
assert.equal(m.billing_name, null);
assert.equal(m.billing_address, null);
assert.equal(m.last4, null);
assert.equal(m.brand, null);
assert.match(String(m.provider_token), /^revoked:/);

// 5. Financial records retained but anonymized.
const payments = await pool.query(`SELECT customer_snapshot,description,status,amount,currency,provider_payment_id FROM payments.payment_intents WHERE customer_id=$1`, [customerId]);
assert.ok(payments.rowCount! >= 1, 'payment retained');
for (const p of payments.rows) {
  assert.deepEqual(p.customer_snapshot, { id: customerId, status: 'erased' });
  assert.equal(p.description, null);
  assert.ok(['succeeded'].includes(p.status));
}
const refunds = await pool.query(`SELECT customer_email,reason FROM payments.refunds WHERE payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE customer_id=$1)`, [customerId]);
for (const r of refunds.rows) { assert.equal(r.customer_email, null); assert.equal(r.reason, 'redacted'); }
const invoices = await pool.query(`SELECT billing_snapshot,object_key,total,currency FROM payments.invoices WHERE customer_id=$1`, [customerId]);
assert.ok(invoices.rowCount! >= 1, 'invoice retained');
for (const inv of invoices.rows) { assert.deepEqual(inv.billing_snapshot, { status: 'erased' }); assert.equal(inv.object_key, null); }

// 6. Ledger/captures intact (financial meaning preserved).
const captures = await pool.query(`SELECT count(*)::int FROM payments.captures c JOIN payments.payment_intents p ON p.id=c.payment_intent_id WHERE p.customer_id=$1 AND c.status='succeeded'`, [customerId]);
assert.ok(Number(captures.rows[0]!.count) >= 1, 'capture preserved');

// 7. Provider sandbox profile anonymized.
const provider = await pool.query(`SELECT email,name,external_reference FROM provider_sandbox.customers WHERE payflow_customer_id=$1`, [customerId]);
for (const p of provider.rows) { assert.equal(p.email, 'erased'); assert.equal(p.name, 'Erased'); assert.equal(p.external_reference, 'erased'); }

// 8. Operational PII removed.
const ops = await pool.query<{ table: string; count: number }>(`
  SELECT 'analytics_events' AS table, count(*)::int count FROM operations.analytics_events WHERE customer_id=$1
  UNION ALL SELECT 'notification_preferences', count(*)::int FROM operations.notification_preferences WHERE customer_id=$1
  UNION ALL SELECT 'notifications', count(*)::int FROM operations.notifications WHERE customer_id=$1
  UNION ALL SELECT 'email_deliveries', count(*)::int FROM operations.email_deliveries WHERE customer_id=$1
  UNION ALL SELECT 'document_manifests', count(*)::int FROM operations.document_manifests WHERE customer_id=$1
`, [customerId]);
for (const row of ops.rows) assert.equal(row.count, 0, `${row.table} still has rows`);

// 9. Outbox payloads for this customer no longer expose PII.
const outbox = await pool.query(`SELECT payload FROM operations.outbox_events WHERE aggregate_id=$1::uuid OR payload->>'customerId'=$1::text`, [customerId]);
for (const row of outbox.rows) {
